import subprocess,json,uuid,pathlib,sys
assert len(sys.argv)>1, 'Explicit locally cached image required; this fixture never pulls'
image=sys.argv[1]
case=sys.argv[2] if len(sys.argv)>2 else 'expired'
name='otr-metadata-recovery-'+uuid.uuid4().hex[:12]
node=r'''const fs=require('node:fs');const cp=require('node:child_process');const crypto=require('node:crypto');const mode=process.argv[1];
if(mode!=='absent') { const batchId=crypto.randomUUID(),jobId=crypto.randomUUID(),accountId=crypto.randomUUID();const b={version:1,accountId,batchId,jobId,inputId:crypto.randomUUID(),inputRevision:1,captureId:crypto.randomUUID(),payloadId:crypto.randomUUID(),captureRevision:1,sha256:'a'.repeat(64),byteCount:16,mediaType:'application/pdf'};const body={version:1,directory:'/var/lib/otr/capture-custody',identity:{store_id:crypto.randomUUID(),device:'1',inode:'2'},expiresAt:'2026-10-17T08:33:27.096Z',batch:{batchId,jobId,inputs:[b,{...b,inputId:crypto.randomUUID(),captureId:crypto.randomUUID()}]}};fs.writeFileSync('/run/otr/capture-custody.json',mode==='malformed'?'{}':JSON.stringify(body));fs.chownSync('/run/otr/capture-custody.json',0,999);fs.chmodSync('/run/otr/capture-custody.json',mode==='denied'?0o000:0o440);}
process.setgroups([999]);process.setgid(10001);process.setuid(10001);const child=cp.spawn('node',['/app/server-capture.mjs'],{stdio:['ignore','pipe','pipe']});let stdout='',stderr='';child.stdout.on('data',b=>stdout+=b);child.stderr.on('data',b=>stderr+=b);let done=false;
child.on('exit',(code,signal)=>{if(done)return;done=true;console.log(JSON.stringify({case:mode,state:'EXITED_BEFORE_HEALTH',code,signal,stdout,stderr}));});
setTimeout(async()=>{if(done)return;try{const r=await fetch('http://127.0.0.1:8787/health');const health=await r.json();const id='11111111-1111-4111-8111-111111111111';const routes={};for(const path of ['/v2/trips/'+id+'/metadata','/v2/trip-metadata-operations/'+id,'/v2/trip-create-operations/'+id,'/v2/trips/'+id+'/source-import-catalogs','/v2/trips/'+id+'/ledger/bootstrap']){const q=await fetch('http://127.0.0.1:8787'+path,{headers:{'OTR-Trip-Metadata-Version':'2','OTR-Metadata-Operation-Id':id}});routes[path]={status:q.status,body:await q.json()};}done=true;console.log(JSON.stringify({case:mode,state:'HEALTH_RESPONSE',status:r.status,health,routes,stdout,stderr}));child.kill('SIGTERM');}catch(e){done=true;console.log(JSON.stringify({case:mode,state:'NO_HEALTH',error:e.code||e.name,stdout,stderr}));child.kill('SIGTERM');}},6500);
setTimeout(()=>{child.kill('SIGKILL');process.exit(0)},8000);'''
args=['/opt/homebrew/bin/docker','run','--name',name,'--network','none','--read-only','--tmpfs','/run/otr:mode=0755','--tmpfs','/tmp:mode=1777','--user','0','-e','OTR_DEV_BACKEND_NETWORK_MODE=host','-e','OTR_DEV_BACKEND_BIND_ADDRESS=127.0.0.1','-e','OTR_DEV_SUPABASE_URL=https://tuqigdxrvrerfewsxqgm.supabase.co','-e','OTR_DEV_SUPABASE_PUBLISHABLE_KEY=synthetic-no-network-publishable','-e','OTR_DEV_SUPABASE_SECRET_KEY=synthetic-no-network-secret','-e','OTR_DEV_FLIGHT_ONE_SHOT=disabled','-e','OTR_DEV_FLIGHT_REMOTE_TRANSPORT=disabled','-e','OTR_DEV_SOURCE_PDF2_TRANSPORT=CLOSED',image,'node','-e',node,case]
try:
 r=subprocess.run(args,capture_output=True,text=True,timeout=25);assert r.returncode==0,r.stderr;out=json.loads(r.stdout.strip());inspect=json.loads(subprocess.check_output(['/opt/homebrew/bin/docker','inspect',name]))[0];out.update({'image':inspect['Image'],'network':inspect['HostConfig']['NetworkMode'],'syntheticOnly':True,'actualDEVConfigCopied':False});print(json.dumps(out,indent=2))
finally:subprocess.run(['/opt/homebrew/bin/docker','rm','-f',name],capture_output=True)
